### 🐛 Describe the bug

I was loosely following the Karpathy tutorial [Let's reproduce GPT-2 (124M)
](https://www.youtube.com/watch?v=l8pRSuU81PU) and I got a torch compilation error when trying to use torch.compile on my gpt2 implementation.

For my full script, see [train_gpt2.py.txt](https://github.com/user-attachments/files/21203146/train_gpt2.py.txt)

For the full stderr for my model, see [bug_report.txt](https://github.com/user-attachments/files/21203123/bug_report.txt).

The most relevant seeming part of the stack trace is:
```
  File "/Users/ian/gg/learnllm/gpt2-repro/v/lib/python3.13/site-packages/torch/_inductor/runtime/runtime_utils.py", line 181, in compile_mps_shader
    raise SyntaxError(f"failed to compile {source} with {err.msg}") from err
torch._inductor.exc.InductorError: SyntaxError: failed to compile 
    #include <c10/metal/random.h>
    #include <c10/metal/special_math.h>
    #include <c10/metal/utils.h>
    #include <c10/metal/reduction_utils.h>
    kernel void generated_kernel(
        device float* out_ptr0,
        device float* out_ptr2,
        constant float* in_ptr0,
        uint2 thread_pos [[thread_position_in_grid]],
        uint2 group_pos [[thread_position_in_threadgroup]]
    ) {
        auto xindex = thread_pos.x;
        auto r0_index = thread_pos.y;
        int x0 = xindex;
        threadgroup float tmp_acc_0[1024];
        tmp_acc_0[r0_index] = ::metal::numeric_limits<float>::lowest();
        threadgroup float tmp_acc_1[1024];
        for(auto r0_1_cnt = 0; r0_1_cnt < 50; ++r0_1_cnt) {
            int r0_1 = 50 * r0_index + r0_1_cnt;
            if (r0_1 >= 50257) break;
            auto tmp0 = in_ptr0[r0_1 + 50257*x0];
            tmp_acc_0[r0_index] = ::c10::metal::max(tmp_acc_0[r0_index], tmp0);
        }
        auto tmp1 = c10::metal::threadgroup_max(tmp_acc_0, 1024);
        out_ptr0[x0] = static_cast<float>(tmp1);
        auto tmp2 = tmp0 - tmp1;
        auto tmp3 = metal::exp(tmp2);
        tmp_acc_1[r0_index] = tmp3;
        auto tmp4 = c10::metal::threadgroup_sum(tmp_acc_1, 1024);
        auto tmp5 = metal::log(tmp4);
        out_ptr2[x0] = static_cast<float>(tmp5);
    }
 with program_source:845:25: warning: comparison of integers of different signs: 'int' and 'unsigned int' [-Wsign-compare]
  for (int idx = 1; idx < size; ++idx) {
                    ~~~ ^ ~~~~
program_source:858:25: warning: comparison of integers of different signs: 'int' and 'unsigned int' [-Wsign-compare]
  for (int idx = 1; idx < size; ++idx) {
                    ~~~ ^ ~~~~
program_source:889:21: error: use of undeclared identifier 'tmp0'; did you mean 'tmp1'?
        auto tmp2 = tmp0 - tmp1;
                    ^~~~
                    tmp1
program_source:887:14: note: 'tmp1' declared here
        auto tmp1 = c10::metal::threadgroup_max(tmp_acc_0, 1024);
             ^
```

My guess is that whatever script is generating the metal shaders is seeing that tmp0 is declared in the for loop, but doesn't understand that it doesn't live past the end of the for loop.


